const {Q,F}=require('../author.cjs');
const q=(id,los,stem,options,solution,section,pool='practice')=>Q('dig-'+id,'digital-assets','alternatives',pool,los,stem,options,0,solution,{section});
const n=(id,los,stem,options,tex,reading,section,meaning,pool='practice')=>q(id,los,stem,options,[F(tex,reading,[['Z',meaning]])],section,pool);
module.exports=[
 q('01','a','A distributed ledger is most directly useful to financial participants when it:',[['Supports an agreed shared state and rules for valid updates among relevant parties.','Gemeinsamer Zustand und gemeinsame Änderungsregeln können Abstimmungsprobleme reduzieren.'],['Guarantees that every underlying borrower will repay.','Ein Register beseitigt das Kreditrisiko des Schuldners nicht.'],['Automatically creates a contractual cash flow for every token.','Der Zahlungsanspruch muss aus den tatsächlichen Rechten folgen.']],['Die technische Organisation und der wirtschaftliche Anspruch sind getrennte Analyseebenen.'],'ledger'),
 q('02','a','Which statement best distinguishes blockchain from the wider category of distributed ledger technology?', [['A blockchain uses cryptographically linked blocks; distributed ledgers need not all use that structure.','Die Blockstruktur ist eine bestimmte technische Form verteilter Register.'],['Every digital bank balance must be a public blockchain token.','Digital gespeicherte Bankdaten sind nicht automatisch ein solcher Token.'],['A distributed ledger can never have permissioned participants.','Berechtigte Teilnehmer sind eine mögliche Architekturgestaltung.']],['Die Technologie wird nach ihrer tatsächlichen Architektur eingeordnet.'],'map'),
 q('03','a','Two proposed payments each appear affordable against the same old balance, but cannot both be funded. A ledger system needs:',[['A common ordering and validation against the updated available state.','Jede gültige Zahlung verändert die danach noch verfügbaren Mittel.'],['Only two copies of the unchanged opening balance.','Kopien allein entscheiden den konkurrierenden Verbrauch nicht.'],['An assumption that both payments create new currency.','Eine Übertragung erzeugt ohne entsprechende Regel keinen zusätzlichen Bestand.']],['Gemeinsame Datenhaltung allein löst widersprüchliche Zustandsänderungen nicht.'],'transaction'),
 n('04','a','A has 120 units and sends 80 to B while paying a separate 3-unit fee to V. B and V start at zero; no issuance occurs. A’s remaining balance is:',[['37.00.','Beide tatsächlichen Abgänge werden vom Anfangsbestand abgezogen.'],['40.00.','Das ignoriert die zusätzliche Gebühr.'],['43.00.','Das addiert die Gebühr statt sie abzuziehen.']],'Z=120-80-3=37','Zahlung und Gebühr besitzen unterschiedliche Empfänger, belasten aber beide A.','transaction','Nach der vollständigen eigenen Übertragung verfügbarer Bestand von A, Einheiten.'),
 q('05','a','A cryptographic hash and encryption have different primary purposes because:',[['A hash can reveal changed data, while encryption aims to restrict readable access.','Integritätshinweis und Vertraulichkeit sind verschiedene Funktionen.'],['Hashing automatically makes every transaction secret.','Öffentlich lesbare Daten können gehasht sein.'],['Encryption by itself establishes the economic value of a token.','Vertraulichkeit legt keinen Marktwert oder Zahlungsanspruch fest.']],['Signaturen, Hashing und Verschlüsselung dürfen nicht gleichgesetzt werden.'],'signatures'),
 q('06','a','A valid digital signature on a transaction most directly supports a conclusion about:',[['Authorization under the relevant cryptographic signing rules.','Die technische Prüfung verbindet Nachricht und passende Signierberechtigung.'],['Truth of every off-chain delivery statement in the message.','Eine Signatur beweist nicht automatisch die Wahrheit der unterschriebenen Information.'],['A guarantee that the signer has not stolen access credentials.','Die wirtschaftliche Berechtigung kann trotz technischer Autorisierung verletzt sein.']],['Technische Autorisierung ist nicht jede rechtliche oder wirtschaftliche Frage.'],'signatures'),
 q('07','a','A permissioned financial ledger may appropriately distinguish:',[['Reading records, submitting transactions, validating updates and changing rules.','Verschiedene Rollen können unterschiedliche Zulassungen besitzen.'],['Only a single universal permission identical for every possible activity.','Ein solches Einheitsrecht folgt nicht aus dem Begriff.'],['A guarantee that all data is publicly visible worldwide.','Berechtigte Register können Zugriff begrenzen.']],['Offenheit muss für die konkrete Funktion bestimmt werden.'],'permission'),
 q('08','a','A proof-of-stake system is best described, at this general level, as one where:',[['Specified participation and incentives depend on assigned or committed stake under that system’s rules.','Die genaue Validator-, Reward- und Sanktionsregel muss zusätzlich geprüft werden.'],['Every holder receives the same risk-free bank interest.','Staking ist kein allgemeines risikoloses Bankversprechen.'],['Governance and validator concentration can never matter.','Konzentration und Regeländerungen bleiben mögliche Abhängigkeiten.']],['Ein Mechanismenname ersetzt keine konkrete Protokollanalyse.'],'consensus'),
 q('09','a','Consensus about a stored market price does not by itself establish that:',[['The external price observation was accurate and timely.','Mehrere Teilnehmer können sich über dieselbe falsche Eingabe einig sein.'],['The recorded value is available to the agreed system.','Gerade der gemeinsam gespeicherte Zustand ist eine Funktion des Registers.'],['The system has any validation rule at all.','Die Frage setzt bereits einen betrachteten Konsensmechanismus voraus.']],['Das Oracle-Problem betrifft die Verbindung der externen Beobachtung mit der internen Verarbeitung.'],'oracle'),
 q('10','a','A smart contract transfers funds after an incorrect delivery confirmation. The best diagnosis is:',[['Correct code execution can coexist with incorrect external input and economic loss.','Der Code kann eine falsche Meldung exakt nach Regel verarbeiten.'],['The transfer proves that the physical delivery actually happened.','Das Register besichtigt die Ware nicht selbst.'],['The term smart guarantees a complete legal remedy in every country.','Der Name begründet keine universelle Rechtsdurchsetzung.']],['Eingabequelle, Ausführung und tatsächlicher Rückgriff müssen zusammen geprüft werden.'],'smart-contract'),
 q('11','a','A proposed delivery-versus-payment arrangement is genuinely atomic under its stated rules if:',[['Both required transfers become effective together or neither does.','Die beiden Seiten gehören zur gleichen verbindlichen Bedingung.'],['The token transfers now and a disconnected bank payment may arrive later.','Ohne zusätzliche Kopplung besteht gerade ein einseitiges Erfüllungsrisiko.'],['The buyer makes two unrelated purchases of the same underlying claim.','Das wäre keine Definition atomarer Lieferung gegen Zahlung.']],['Technische und rechtliche Wirksamkeit beider Seiten ist zu prüfen.'],'dvp'),
 n('12','a','A bond has total nominal 2000 and a total annual coupon of 80. It is split into 40 equal tokens without additional rights or costs. Annual coupon per token is:',[['2.00.','Der gesamte Kupon wird auf vierzig gleiche Ansprüche verteilt.'],['80.00.','Das würde den gesamten Kupon jedem Token nochmals zuordnen.'],['50.00.','Das ist das anteilige Nominal, nicht der Kupon.']],'Z=80/40=2','Die digitale Stückelung vermehrt nicht die gesamte Emittentenpflicht.','tokenization','Jährlicher Kuponanspruch je gleich ausgestaltetem Token, WE.'),
 q('13','a','Tokenizing a conventional bond most directly changes its:',[['Representation or transfer arrangements, while its actual credit and cash-flow terms still require analysis.','Die technische Form ersetzt keine Bonitäts- und Vertragsprüfung.'],['Issuer’s contractual coupon into a risk-free central-bank guarantee.','Eine solche Garantie folgt nicht aus Tokenisierung.'],['Maturity into an automatically perpetual obligation.','Die Laufzeit bleibt eine konkrete Vertragsbedingung.']],['Technische Abbildung und wirtschaftliche Zahlungsquelle sind getrennt.'],'tokenization'),
 q('14','a','For a token referencing physical inventory, the ledger alone cannot guarantee:',[['That the off-chain goods exist, match the description and are legally claimable.','Dafür werden externe Nachweise und wirksame Rechte benötigt.'],['That a digital reference can be stored.','Die Speicherung eines digitalen Verweises ist technisch möglich.'],['That a system can record a transfer instruction.','Die Frage betrifft die zusätzliche externe Realität.']],['Die Verbindung zur Außenwelt muss eigenständig geprüft werden.'],'oracle'),
 q('15','a','Blockchain immutability is most accurately discussed as:',[['Tamper evidence and resistance conditional on the actual network, rules and implementation.','Ein Schutzmechanismus ist nicht absolut unabhängig von allen Systembedingungen.'],['An unconditional inability to change any record under every possible scenario.','Forks, Governance und Netzwerkbedingungen können relevant sein.'],['A guarantee that the original input was economically correct.','Eine dauerhaft gespeicherte falsche Eingabe bleibt falsch.']],['NIST unterscheidet Manipulationsresistenz von absoluter Unveränderlichkeit.'],'finality'),
 q('16','a','A public blockchain is accessed through one centralized custodian. The investor should recognize:',[['A possible centralized access and custody dependency despite the underlying network’s openness.','Die Zugangsebene kann andere Abhängigkeiten als das Register besitzen.'],['The impossibility of any custodian failure because the chain is public.','Netzwerkoffenheit garantiert nicht die Bonität des Dienstleisters.'],['A complete absence of contractual withdrawal conditions.','Der Intermediär kann eigene konkrete Bedingungen haben.']],['Die gesamte Anspruchs- und Zugangskette muss betrachtet werden.'],'permission'),
 q('17','a','Which proposed financial application most directly uses programmable conditional execution?', [['Releasing a specified payment only when the agreed validated condition is met.','Bedingte Ausführung kann einen definierten Prozess automatisieren.'],['Declaring all future asset prices known with certainty.','Ein Programm kennt künftige Marktpreise nicht automatisch.'],['Turning every input into a legally valid fact by storing it.','Datenspeicherung ersetzt keine Tatsachen- und Rechtsprüfung.']],['Die Anwendung muss nach tatsächlicher Bedingung und Datenherkunft beurteilt werden.'],'smart-contract'),
 q('18','a','Using a central database may be preferable when:',[['Participants accept one trusted operator and the simpler architecture meets the actual requirements.','DLT ist eine technische Wahl für ein konkretes Problem und kein Selbstzweck.'],['A blockchain name alone guarantees lower total operating costs.','Ein solcher Kostenvorteil ist nicht allgemein garantiert.'],['No one needs consistent records or access control.','Die genannten Grundanforderungen können auch zentral wichtig sein.']],['Nutzen, Aufwand und Governance werden gegen den tatsächlichen Anwendungsfall geprüft.'],'ledger'),
 q('19','a','A technically final token transfer is best evaluated together with:',[['The applicable legal effectiveness and rights associated with the transferred claim.','Technische Finalität beantwortet nicht automatisch alle externen Rechtsfragen.'],['An assumption that every jurisdiction recognizes identical title effects.','Das wäre eine unzulässige universelle Rechtsannahme.'],['A guaranteed increase in the asset’s fundamental value.','Endgültigkeit einer Übertragung schafft keinen sicheren Mehrwert.']],['Registerzustand und durchsetzbarer Anspruch sind verschiedene Ebenen.'],'finality'),
 q('20','a','The strongest application case for a shared ledger should explain:',[['Which reconciliation or coordination problem it solves and how validation and governance work.','Ein überprüfbarer Nutzen benötigt einen konkreten Prozess.'],['Only that the word blockchain appears in the product name.','Ein Etikett beschreibt keine funktionierende Anwendung.'],['Only the highest historical token price.','Ein Marktpreis ist kein Nachweis des technischen Prozessnutzens.']],['Anwendung, Regelwerk und wirtschaftliche Wirkung gehören in denselben Analyseweg.'],'workflow'),
 q('21','b','A native token with no contractual redemption or distribution right should not automatically be valued as:',[['A conventional bond promising fixed coupon and principal payments.','Für diese Zahlungen müsste ein entsprechender Anspruch bestehen.'],['An asset whose price may depend on demand and usage expectations.','Solche Erwartungen können gerade relevant sein.'],['An asset whose supply rules and governance merit investigation.','Diese Merkmale gehören zur Analyse.']],['Ein Cashflow darf nicht allein zur Rechtfertigung eines Bewertungsmodells erfunden werden.'],'native'),
 n('22','b','An own one-year tokenized claim pays 1080 with certainty under the stated scenario. At a matching 12% annual discount rate, present value is closest to:',[['964.285714.','Die eine vollständige Endzahlung wird durch 1,12 diskontiert.'],['1080.000000.','Das ignoriert die Wartezeit und den geforderten Diskont.'],['1000.000000.','Das wäre der Wert bei acht statt zwölf Prozent.']],'Z=1080/1{,}12\\approx964{,}285714','Die technische Tokenform ändert nicht die angegebene Diskontierung.','valuation','Heutiger Wert des vollständig bezeichneten Einjahresanspruchs, WE.'),
 n('23','b','An own claim pays 60 in total and incurs 6 of costs before equal distribution to 30 tokens. No other rights or flows exist. Net payment per token is:',[['1.80.','Vierundfünfzig verfügbare WE geteilt durch dreißig gleiche Token.'],['2.00.','Das ignoriert die Kosten vor Verteilung.'],['54.00.','Das ist der Gesamtbetrag statt der Zahlung je Token.']],'Z=(60-6)/30=1{,}8','Bruttoreferenz und tatsächliche anteilige Nettozahlung werden übergeleitet.','claims-case','Nettocashflow je gleichberechtigtem Token, WE.'),
 n('24','b','An own consistently defined aggregate token valuation is 4 million and the relevant supply is 2 million identical units. Implied unit price is:',[['2.00.','Bewertung geteilt durch die dazu passende Menge.'],['8.00.','Das multipliziert statt zu dividieren.'],['0.50.','Das vertauscht Menge und Bewertung.']],'Z=4/2=2','Das ist eine Identität für die gegebenen Werte, keine Nachfrageprognose.','supply','Aus den bezeichneten Größen abgeleiteter Preis je Einheit, WE.'),
 q('25','b','A token has a fixed maximum supply. That fact by itself establishes:',[['Neither a particular level of future demand nor a guaranteed price floor.','Knappheit allein bestimmt keinen sicheren Marktpreis.'],['A guaranteed positive price return in every period.','Nachfrage und andere Risiken können sich ungünstig verändern.'],['A contractual right to the issuer’s entire revenue.','Ein Zahlungsanspruch folgt nicht aus der Angebotsgrenze.']],['Angebot, Nutzen, Nachfrage und Rechte müssen getrennt untersucht werden.'],'native'),
 n('26','b','An own investor starts with 100 tokens, receives gross rewards of 20% of opening quantity and pays 25% of those new rewards as fees. No other changes occur. Ending quantity is:',[['115.00.','Zwanzig neue Token minus fünf Reward-Gebühr.'],['95.00.','Das zieht 25 Prozent fälschlich vom gesamten Anfangsbestand ab.'],['120.00.','Das ignoriert die Reward-Gebühr.']],'Z=100+100(0{,}20)(1-0{,}25)=115','Die Gebührenquote wird auf ihre ausdrücklich bezeichnete Basis angewandt.','costs','Eigener Endbestand nach der angegebenen Reward-Gebühr, Token.'),
 q('27','b','A governance token most directly requires investigation of:',[['The actual decision rights, their limits and whether any cash-flow rights exist.','Mitwirkung und wirtschaftliche Zahlung sind nicht dieselbe Funktion.'],['A guaranteed equal share of every platform revenue item.','Ein solcher Anspruch muss gesondert bestehen.'],['A guarantee that governance rules can never change.','Änderungs- und Kontrollrechte sind gerade zu prüfen.']],['Die Analyse beginnt beim konkreten Recht und nicht beim Namen.'],'categories'),
 q('28','b','An NFT referencing an artwork most directly establishes:',[['Only the rights actually associated with that token and its agreement.','Urheber-, Nutzungs- und Herausgaberechte sind konkret festzulegen.'],['Automatic transfer of every worldwide copyright and usage right.','Ein technischer Verweis gewährleistet das nicht.'],['Guaranteed permanent access to any externally stored file.','Externe Speicherung kann eigene Ausfallabhängigkeiten besitzen.']],['Individueller Datensatz und vollständige Rechte am Bezugsobjekt sind verschieden.'],'nft'),
 q('29','b','Which statement correctly distinguishes a private stablecoin from central-bank money?', [['The issuer, legal claim and support mechanism can differ even if both reference the same currency.','Gleiche Recheneinheit macht die Schuldner- und Einlöserrechte nicht identisch.'],['Every private token referencing a currency is a central-bank liability.','Der Referenzname schafft keine solche Schuld.'],['Both must have identical redemption rights in every country.','Die tatsächlichen Regeln und Zugangsformen unterscheiden sich.']],['Währungsbezug und Forderungsgegner müssen separat geprüft werden.'],'stablecoins'),
 q('30','b','A stablecoin depeg is best described as:',[['A deviation from the intended reference price that may reflect several different stresses.','Reservewert, Vertrauen, Liquidität und Einlösung können beitragen.'],['Proof of a particular final legal recovery rate for every holder.','Marktpreis und spätere tatsächliche Verteilung sind nicht identisch.'],['A guarantee that the reference currency itself has ceased to exist.','Die Bindung eines Produkts kann scheitern, ohne dass die Währung verschwindet.']],['Die Ursache und der konkrete Anspruch sind zu untersuchen.'],'stablecoins'),
 n('31','b','An own immediate liquidation realizes reserve assets of 190, pays prior costs of 10 and distributes the rest proportionately against equal claims totaling 200. No other rights exist. Recovery per nominal claim unit is:',[['0.90.','180 verfügbare WE auf 200 nominale Ansprüche.'],['0.95.','Das ignoriert die vorrangigen Kosten.'],['1.00.','Das behandelt die frühere Referenzbindung als garantierte Vollzahlung.']],'Z=(190-10)/200=0{,}9','Die Quote gilt nur für die vollständig bezeichneten eigenen Verteilungsregeln.','reserve-case','Erfüllungsbetrag je nominaler Anspruchseinheit, WE.'),
 q('32','b','A synthetic token references a company’s stock. The investor should not assume without further rights that they:',[['Have a direct voting or dividend claim against the referenced company.','Synthetische Kursabbildung kann allein einen anderen Anspruchsgegner haben.'],['May face the synthetic issuer’s counterparty risk.','Diese zusätzliche Abhängigkeit ist gerade möglich.'],['Need to read the token contract and collateral terms.','Diese Informationen sind zur Einordnung nötig.']],['Referenzpreis und eigene Anspruchsrechte müssen auseinandergehalten werden.'],'rights'),
 q('33','b','A network reports total fees paid by users. Those fees can be treated as tokenholder distributable cash only if:',[['The actual rules create a corresponding attributable payment right.','Erst der Anspruchs- und Zahlungsweg verbindet Aktivität mit Inhaber-Cashflow.'],['The total is large enough to produce a convenient valuation multiple.','Die Größe erzeugt kein fehlendes Recht.'],['The token trades continuously.','Handelszeit bestimmt keine Ausschüttungsberechtigung.']],['Netzwerknutzung ist nicht automatisch Anlegerertrag.'],'network'),
 n('34','b','An asset falls from 100 to 80, then must return to 100 without new contributions. The required subsequent gain is:',[['25.00%.','Zwanzig Gewinn werden auf die verbleibenden achtzig bezogen.'],['20.00%.','Das verwendet noch den ursprünglichen Nenner.'],['80.00%.','Das ist keine korrekte Erholungsrechnung.']],'Z=100(100/80-1)=25','Verlust und Erholung verwenden unterschiedliche Kapitalbasen.','drawdown','Zur vollständigen Erholung nötige Rendite auf den verbleibenden Wert, Prozent.'),
 q('35','b','A tokenized bond’s issuer credit spread rises while its legal cash-flow terms remain unchanged. Its value:',[['Can fall because the required return or expected recovery assessment changes.','Gleiche technische Darstellung beseitigt keine Kredit- oder Diskontänderung.'],['Must remain unchanged because the bond uses DLT.','Das Register garantiert keinen konstanten Marktwert.'],['Must become equal to a central-bank deposit.','Das wäre ein anderer Anspruch.']],['Tokenisierung ersetzt nicht die Analyse wirtschaftlicher Risikotreiber.'],'valuation'),
 q('36','b','A bridge issues a wrapped representation of an asset on another network. The analysis should include:',[['The mechanism and enforceable ability to obtain the referenced underlying asset.','Die Verbindung kann eigene technische und Gegenparteiabhängigkeiten besitzen.'],['An assumption that identical tickers remove every added risk.','Ein Name beweist keine vollständige Einlösung.'],['A guarantee that two networks always reach the same state simultaneously.','Unterschiedliche Konsens- und Verbindungsprozesse können relevant sein.']],['Die zusätzliche Anspruchs- und Übertragungskette ist Teil der Anlageeigenschaften.'],'risk'),
 q('37','b','A token’s market capitalization is computed using a stated supply convention. Comparing it with another figure requires:',[['Consistent treatment of price, circulating or other specified supply, and valuation date.','Unterschiedliche Mengendefinitionen können nicht unbemerkt gleichgesetzt werden.'],['Assuming that every possible supply definition produces the same value.','Ausstehend, umlaufend und vollständig verwässert können verschieden sein.'],['Treating the result as total cash already invested by all buyers.','Preis mal Menge ist kein vollständiger historischer Einzahlungsnachweis.']],['Eine Bewertungsidentität ist nicht automatisch ein Zahlungsfluss oder Marktprognosemodell.'],'supply'),
 q('38','b','A low observed stablecoin price volatility over a short history:',[['Does not rule out rare reserve, redemption or custody losses.','Eine ruhige beobachtete Periode kann schwere seltene Zustände auslassen.'],['Proves identical risk to a sovereign-backed banknote.','Schuldner, Ansprüche und Mechanismus können verschieden sein.'],['Eliminates the need to inspect reserve assets.','Gerade ihre Qualität und Verfügbarkeit sind zu prüfen.']],['Geringe gewöhnliche Schwankung ist keine umfassende Sicherheitsdefinition.'],'stablecoins'),
 q('39','b','A protocol burns some fee tokens. The most defensible conclusion is:',[['Supply effects must be considered with demand and holder rights rather than as guaranteed cash income.','Eine Mengenänderung ist weder ein sicherer Preisgewinn noch eine Cashdividende.'],['Every holder has received the same amount of spendable fiat cash.','Burn überweist diesen Betrag nicht automatisch an Inhaber.'],['Token prices must increase by exactly the burn percentage.','Nachfrage, Bezugsgrößen und andere Änderungen bleiben relevant.']],['Cashflow, Angebotsänderung und Marktpreis werden getrennt verfolgt.'],'network'),
 q('40','b','The strongest first question for an unfamiliar digital asset is:',[['What specific use or enforceable economic right does this unit provide?','Diese Frage bestimmt Zahlungsquelle, Bewertung und wesentliche Risiken.'],['What was its highest quoted price on any platform?','Eine historische Quote erklärt keinen Anspruch.'],['Can its name be grouped with a famous token?','Ähnliche Bezeichnungen machen Anlagen nicht gleichwertig.']],['Die wirtschaftliche Analyse beginnt mit Funktion und Recht.'],'map'),
 q('41','c','For a spot ETP investor, avoiding personal management of underlying private keys:',[['Shifts some tasks to the product and its service providers without eliminating custody risk.','Das Produkt selbst bleibt auf geeignete Verwahrung angewiesen.'],['Eliminates all risks of the underlying crypto asset.','Marktrisiko und Produktebenen bleiben bestehen.'],['Gives the investor direct control of every underlying wallet.','Das ist nicht die übliche Folge des Besitzes eines Produktanteils.']],['Zugangserleichterung und vollständige Risikobeseitigung sind verschiedene Aussagen.'],'spot-etp'),
 n('42','c','An own product holds 3 tokens priced at 40, additional cash 10 and liabilities 4. It has 20 equal shares. NAV per share is:',[['6.30.','126 Nettowerteinheiten geteilt durch zwanzig Anteile.'],['6.50.','Das ignoriert die Verbindlichkeiten.'],['40.00.','Das ist der Tokenpreis statt des Produkt-NAV.']],'Z=[3(40)+10-4]/20=6{,}3','Tokenbestand, weitere Produktpositionen und Anteilzahl werden vollständig verbunden.','spot-etp','Nettovermögenswert je gleichberechtigtem Produktanteil, WE.'),
 n('43','c','A separate own product starts with assets 120, no liabilities and 20 equal shares. It pays a fee of 6 from its assets, with no other changes. NAV per share after payment is:',[['5.70.','114 verbleibende WE geteilt durch zwanzig Anteile.'],['6.00.','Das ist der NAV vor der bezahlten Gebühr.'],['0.30.','Das ist nur die Gebührenbelastung je Anteil.']],'Z=(120-6)/20=5{,}7','Die tatsächlich bezahlte Produktgebühr wird genau einmal vom Vermögen abgezogen.','spot-etp','Nettovermögenswert je Anteil nach der bezeichneten Produktgebühr, WE.'),
 n('44','c','An own ETP trades at 6.6 while its consistently measured NAV per share is 6.3. Premium to NAV is closest to:',[['4.761905%.','Der Aufschlag 0,3 wird auf den NAV 6,3 bezogen.'],['4.545455%.','Das verwendet den Handelspreis als Nenner statt den NAV.'],['0.300000%.','Das verwechselt die absolute Preisdifferenz mit einer Prozentquote.']],'Z=100(6{,}6/6{,}3-1)\\approx4{,}761905','Prämie und absoluter Preisunterschied sind unterschiedliche Größen.','premium','Aufschlag des gehandelten Anteilspreises auf den angegebenen NAV, Prozent.'),
 q('45','c','A futures ETP and a spot product referencing the same asset may have different returns because:',[['Contracts, daily settlement, collateral, rolling and fees create different actual paths.','Die Referenz allein bestimmt den Produkteignertrag nicht vollständig.'],['Every new futures position requires a second full purchase of the underlying asset.','Ein neuer Kontrakt mit Wert null ist kein zusätzlicher voller Spotkauf.'],['Both must have identical custody and legal arrangements.','Die Produkt- und Anspruchsstruktur kann sich unterscheiden.']],['Alle tatsächlichen Positions- und Cashbestandteile sind zu überleiten.'],'futures-etp'),
 q('46','c','Buying stock in a crypto-related operating company rather than holding a token adds exposure to:',[['The company’s operating costs, financing, governance and residual shareholder claims.','Unternehmens- und Tokenanspruch besitzen unterschiedliche Treiber.'],['A guaranteed one-for-one replication of token returns.','Kosten, Verschuldung und Bewertung können die Aktie anders verändern.'],['An absence of any business failure risk.','Ein Unternehmensgeschäft kann scheitern.']],['Indirekte Anlagewege brauchen eine eigene Unternehmensanalyse.'],'listed-equity'),
 q('47','c','A pooled token investment vehicle has withdrawal restrictions. A displayed daily valuation:',[['Is not by itself an enforceable right to receive cash each day.','Bewertung und Anlegerliquidität sind verschiedene Vertragsfragen.'],['Cancels all lock-ups and gates automatically.','Ein Bewertungsbericht hebt Beschränkungen nicht automatisch auf.'],['Guarantees that all underlying assets have deep daily markets.','Die Berichtshäufigkeit bestimmt die tatsächliche Markttiefe nicht.']],['Zugang, Rückgaberegeln und konkrete Zahlungszeitpunkte werden gemeinsam geprüft.'],'due-diligence'),
 n('48','c','An investor buys a product at 120 when NAV per share is 100. Later NAV is still 100 and the investor sells at NAV. No other flows occur. Investor return is:',[['-16.666667%.','Der Verlust zwanzig wird auf den gezahlten Preis 120 bezogen.'],['0.000000%.','Das ist die NAV-Veränderung und nicht die eigene Anlegerpreisrendite.'],['-20.000000%.','Das verwendet den ursprünglichen NAV statt des Kaufpreises als Nenner.']],'Z=100(100/120-1)\\approx-16{,}666667','Eine bezahlte Prämie kann unabhängig vom NAV Verlust erzeugen.','premium','Preisrendite des tatsächlich gekauften Produktanteils, Prozent.'),
 n('49','c','A separate investor buys at 120 when NAV is 100. NAV then rises to 120, and the sale price equals NAV. There are no distributions or costs. Investor return is:',[['0.00%.','Der Ausstiegspreis entspricht nur dem bereits gezahlten Einstiegspreis.'],['20.00%.','Das ist die NAV-Rendite vor Berücksichtigung der anfänglichen Prämie.'],['44.00%.','Das zählt die bezahlte Prämie als zusätzlichen Gewinn.']],'Z=100(120/120-1)=0','Die tatsächliche Kaufbasis ist für die Anlegerrechnung entscheidend.','premium','Preisrendite auf den tatsächlichen Einstiegspreis, Prozent.'),
 q('50','c','With third-party custody, a particularly important additional question is:',[['How customer assets and claims are treated if the provider fails.','Zuordnung und Ausfallansprüche bestimmen den tatsächlichen Rückgriff.'],['Whether the provider’s interface has an attractive color scheme.','Das ist kein Nachweis wirtschaftlicher Anspruchssicherheit.'],['Whether the underlying chain makes provider insolvency impossible.','Netzwerktechnik garantiert nicht die Bonität eines Intermediärs.']],['Verwahrung wird nach tatsächlicher Kontrolle und Rechten untersucht.'],'custody'),
 q('51','c','A cold-storage device is lost, but an authorized, secure and functional recovery method exists. The sound conclusion is:',[['Device loss alone need not imply permanent loss of access.','Der konkrete Wiederherstellungsweg muss in die Beurteilung einbezogen werden.'],['All rights must disappear solely because the physical device is missing.','Das ignoriert die ausdrücklich vorhandene funktionierende Wiederherstellung.'],['Recovery credentials can safely be made public.','Offenlegung kann unberechtigte Kontrolle ermöglichen.']],['Gerät, Signierberechtigung und Wiederherstellung sind getrennte Objekte.'],'keys'),
 n('52','c','An own long futures position covers one reference unit. Futures price rises from 90 to 100 and all variation margin is settled into opening cash of 100. No interest, fees or other flows apply. Closing cash is:',[['110.00.','Zehn abgerechneter Gewinn kommen zur ursprünglichen Kasse hinzu.'],['100.00.','Das ignoriert die tatsächliche Abrechnung.'],['10.00.','Das zeigt nur den Gewinn und lässt das ursprüngliche Cash weg.']],'Z=100+1(100-90)=110','Abgerechneter Gewinn und ursprüngliches Kapital werden genau einmal verbunden.','futures-etp','Verbleibende Kasse nach der vollständigen gegebenen Futuresabrechnung, WE.'),
 q('53','c','A wrapped asset and a direct native holding may differ principally because the wrapped route:',[['Can introduce an additional bridge, custodian or redemption dependency.','Die weitere technische und rechtliche Abbildung benötigt eigene Prüfung.'],['Always gives direct rights identical to every native holding.','Das folgt aus einem ähnlichen Preis oder Namen nicht.'],['Cannot ever lose its reference link.','Die Verbindung kann im Stress oder durch Fehler gestört werden.']],['Die tatsächliche Anspruchskette bestimmt die hinzugefügten Risiken.'],'rights'),
 q('54','c','A trust, an ETF and an ETP are mentioned in marketing. The analyst should:',[['Inspect the actual legal and economic structure rather than assume all names imply identical rules.','Oberbegriffe und konkrete Hüllen müssen unterschieden werden.'],['Apply one jurisdiction’s dated product statement to every country and year.','Das wäre eine nicht gerechtfertigte globale Übertragung.'],['Assume the word ETF eliminates every underlying risk.','Ein Produktname ist keine Verlustversicherung.']],['Der konkrete Vertrag und anwendbare aktuelle Rahmen sind maßgeblich.'],'spot-etp'),
 n('55','c','A crypto-related company has revenue 2.4 million and operating cash costs 2.1 million. Ignoring all other items, operating surplus is:',[['0.30.','Der bezeichnete Überschuss ist Erlös minus die angegebenen Betriebskosten.'],['2.40.','Das ist Umsatz vor Kosten.'],['2.10.','Das ist die Ausgabenseite und nicht der Überschuss.']],'Z=2{,}4-2{,}1=0{,}3','Eine Unternehmensanlage braucht ihre eigene Kosten- und Anspruchsrechnung.','listed-equity','Bezeichneter operativer Überschuss vor weiteren ausgeklammerten Ebenen, Millionen WE.'),
 q('56','c','Delegating staking through a provider requires attention to:',[['Provider rights, fees, withdrawal conditions and how protocol losses reach the investor.','Eine weitere Dienstleistungsebene verändert den eigenen Zahlungs- und Risikoweg.'],['Only the highest gross reward percentage in the advertisement.','Ein Bruttowert zeigt Kosten und Ausstieg nicht vollständig.'],['A guarantee that delegation removes all technical and market risk.','Delegation ist keine vollständige Risikobeseitigung.']],['Wirtschaftlicher Anspruch und Umsetzung müssen bis zum Anleger verfolgt werden.'],'rewards'),
 q('57','c','Which distinction matters most when comparing a tokenized fund share with a synthetic token referencing that fund?', [['Actual ownership or intermediary rights versus a separate linked payment claim.','Die Anspruchsgegner und Ausfallwege können verschieden sein.'],['Whether both tickers have the same number of letters.','Die technische Benennung beschreibt keine Anlegerrechte.'],['Whether both must pay an identical guaranteed price tomorrow.','Ein solcher Anspruch folgt nicht aus der gemeinsamen Referenz.']],['Ähnliche Kursbewegungen beweisen keine identischen Rechte.'],'rights'),
 q('58','c','Self-custody most directly shifts responsibility toward the investor for:',[['Maintaining authorized signing access and a secure recovery arrangement.','Die Kontrolle verlangt einen funktionierenden eigenen Umgang mit Berechtigungen.'],['Guaranteeing the future market price.','Verwahrungsart legt keinen zukünftigen Marktpreis fest.'],['Removing the need to understand the token’s actual rights.','Technischer Besitz ersetzt diese Analyse nicht.']],['Eigenverantwortung für Zugriff ist von Markt- und Anspruchsanalyse zu unterscheiden.'],'custody'),
 q('59','c','A platform lends or pledges customer assets under its terms. The investor should examine:',[['Authorization, asset segregation, claim priority and consequences if the borrower or platform fails.','Die weitere Nutzung kann Rückgriff und Verfügbarkeit verändern.'],['Only the original on-chain creation date of the asset.','Das beantwortet die zusätzliche Kredit- und Anspruchsfrage nicht.'],['An assumption that lending is riskless because the asset is digital.','Digitale Darstellung beseitigt Ausfall nicht.']],['Nutzung durch Dritte und eigene verbleibende Rechte gehören in dieselbe Analyse.'],'custody'),
 q('60','c','The most complete comparison of digital-asset investment vehicles includes:',[['Underlying exposure, claim chain, custody, costs, liquidity, pricing and suitability.','Der Anlegerertrag entsteht aus dem gesamten Zugang und seinen Bedingungen.'],['Only whether all products reference the same token.','Die Referenz allein erfasst weder Kosten noch Rechte.'],['Only the most recent one-day return.','Ein einzelner Zeitraum belegt keine vollständige Eignung.']],['Der konkrete Anlagezweck und die tatsächliche Umsetzung bestimmen den Vergleich.'],'workflow'),
 n('61','d','An own investor’s token quantity grows 10% annually, while total supply also grows 10% annually and aggregate valuation is unchanged. Initial wealth is 1000, with no loss or other cost. Wealth after two years is:',[['1000.00.','Gleiche Mengen- und Angebotsfaktoren heben sich bei gleicher Gesamtbewertung auf.'],['1210.00.','Das zählt den Mengenanstieg und ignoriert den niedrigeren Stückpreis.'],['810.00.','Das zieht beide Angebotswirkungen unpassend als separate Verluste ab.']],'Z=1000[(1{,}1)/(1{,}1)]^2=1000','Das eigene Angebotsgewicht bleibt unverändert.','quantity-case','Endvermögen unter den vollständigen eigenen Zweijahresannahmen, WE.'),
 n('62','d','An own two-year scenario has gross annual token reward 8%, a fee of 25% of new rewards, annual supply growth 10%, unchanged aggregate valuation and no loss. Wealth return is closest to:',[['-7.140496%.','Netto-Bestandsfaktor 1,06 wird durch Angebotsfaktor 1,10 geteilt und zweifach verkettet.'],['12.360000%.','Das berücksichtigt nur den Netto-Mengenzuwachs.'],['-8.000000%.','Das subtrahiert Raten linear statt Faktoren zu verketten.']],'Z=100[(1{,}06/1{,}10)^2-1]\\approx-7{,}140496','Bestands- und Preisfaktoren werden vor der Renditebildung vollständig verbunden.','quantity-case','Gesamte zweijährige Vermögensrendite, Prozent.'),
 n('63','d','In an own three-year model, net token quantity growth and total supply growth are each 10% annually, aggregate valuation is unchanged, and a 20% quantity loss occurs exactly once after year-one rewards. No other effects apply. Wealth return is:',[['-20.00%.','Die jährlichen Wachstumsfaktoren heben sich auf; der einmalige Faktor 0,8 bleibt.'],['-48.80%.','Das wiederholt den ausdrücklich einmaligen Verlust in jedem Jahr.'],['10.00%.','Das ignoriert den eigenen Verlust und die Preisbasis.']],'Z=100[(1{,}1/1{,}1)^3(0{,}8)-1]=-20','Einmalige und wiederkehrende Ereignisse sind nicht austauschbar.','loss','Gesamte dreijährige Vermögensrendite nach dem einmaligen Verlust, Prozent.'),
 q('64','d','A user increases the calculator’s aggregate valuation growth while keeping own quantity and global supply paths unchanged. This:',[['Changes price and wealth but not the investor’s fraction of the specified supply.','Der Angebotsanteil verwendet zwei Mengen und keine Geldbewertung.'],['Automatically increases the investor’s fraction of total token units.','Keiner der beiden Mengenbestände wurde geändert.'],['Proves that the entered valuation growth will occur in the market.','Eine Szenarioeingabe ist keine Preisprognose.']],['Der Nenner des Angebotsanteils unterscheidet sich vom Geldwert.'],'quantity-case'),
 n('65','d','An investor’s holding rises from 100 to 120 tokens while the consistently defined total supply rises from 1000 to 1500. Relative change in the investor’s supply share is:',[['-20.00%.','Der Anteil fällt von zehn auf acht Prozent, also relativ um zwanzig Prozent.'],['20.00%.','Das zeigt nur den Anstieg der eigenen Tokenanzahl.'],['-2.00%.','Das verwechselt die Differenz von zwei Prozentpunkten mit der relativen Veränderung.']],'Z=100[(120/1500)/(100/1000)-1]=-20','Anteil, Prozentpunkte und relative Anteilsänderung benötigen unterschiedliche Beschriftungen.','rewards','Relative Veränderung des eigenen Anteils am Gesamtangebot, Prozent.'),
 n('66','d','An asset earns 10% in USD, while EUR per USD falls 10%. With no other flows, the euro investor’s nominal return is:',[['-1.00%.','1,10 mal 0,90 ergibt 0,99 des ursprünglichen Eurovermögens.'],['0.00%.','Das addiert die Raten und ignoriert den Produkteffekt.'],['20.00%.','Das verwendet die falsche Wechselkursrichtung.']],'Z=100[1{,}1(0{,}9)-1]=-1','Die Wechselkursangabe bezeichnet ausdrücklich Heimatwährung je Fremdwährung.','real-fx','Nominale Geldrendite des Euroanlegers, Prozent.'),
 n('67','d','An investment earns 8% in the investor’s home currency over a year. The corresponding home consumption basket rises 5%. Real return is closest to:',[['2.857143%.','Der nominale Endwertfaktor wird durch den Preisniveau-Faktor geteilt.'],['3.000000%.','Das ist nur die lineare Näherung aus der Ratendifferenz.'],['13.000000%.','Das addiert Inflation zum nominalen Ertrag.']],'Z=100(1{,}08/1{,}05-1)\\approx2{,}857143','Verbraucherpreisinflation ist keine zusätzliche Tokenangebotsquote.','real-fx','Rendite relativ zur bezeichneten heimischen Kaufkraft, Prozent.'),
 n('68','d','Following a 60% loss and no new contributions, the subsequent gain needed to recover the original value is:',[['150.00%.','Sechzig verlorene Einheiten werden auf vierzig verbleibende bezogen.'],['60.00%.','Das verwendet noch den ursprünglichen Nenner.'],['40.00%.','Das ist der verbleibende Kapitalanteil.']],'Z=100(0{,}6/0{,}4)=150','Eine tiefe Verlustbasis verlangt eine überproportionale Erholung.','drawdown','Zur vollständigen Erholung nötige Rendite auf den verbleibenden Wert, Prozent.'),
 n('69','d','An own portfolio has weights 95% traditional and 5% digital, component volatilities 15% and 80%, and zero correlation on the same period basis. Portfolio volatility is closest to:',[['14.800760%.','Wurzel aus den beiden gewichteten Einzelvarianzen.'],['18.250000%.','Das ist die gewichtete Volatilität beim perfekten positiven Gleichlauf.'],['15.000000%.','Das ist nur die traditionelle Einzelanlage.']],'Z=\\sqrt{(0{,}95)^2(15)^2+(0{,}05)^2(80)^2}\\approx14{,}800760','Die Kovarianz ist nur unter der hier ausdrücklich gegebenen Nullkorrelation null.','diversification','Portfoliovolatilität in den gleichen Prozent- und Zeitraumseinheiten.'),
 n('70','d','The same 95%/5% weights and 15%/80% component volatilities instead have correlation +1. Portfolio volatility is:',[['18.25%.','Bei perfektem positivem Gleichlauf addieren sich die gewichteten Volatilitäten.'],['14.80%.','Das ist ungefähr der separate Nullkorrelationsfall.'],['4.00%.','Das berücksichtigt nur den gewichteten digitalen Teil.']],'Z=0{,}95(15)+0{,}05(80)=18{,}25','Die Wirkung der Beimischung hängt von der gemeinsamen Bewegung ab.','diversification','Portfoliovolatilität bei perfekter positiver Korrelation, Prozent.'),
 n('71','d','An own portfolio starts 90% traditional and 10% digital, with no rebalancing. Period returns are -10% and -70%, respectively. No other flows occur. Portfolio return is:',[['-16.00%.','Neun Prozentpunkte traditioneller Verlust plus sieben digitale Verlustbeiträge.'],['-40.00%.','Das bildet einen ungewichteten Durchschnitt statt der angegebenen Gewichte.'],['-7.00%.','Das zeigt nur den digitalen Verlustbeitrag.']],'Z=0{,}9(-10)+0{,}1(-70)=-16','Die Verlustbeiträge verwenden denselben ursprünglichen Portfoliowert.','diversification','Gesamte Periodenrendite des bezeichneten Portfolios, Prozent.'),
 q('72','d','Low historical correlation between a digital asset and equities should be interpreted as:',[['A sample- and regime-dependent observation rather than a guaranteed crisis hedge.','Gemeinsame Treiber und Messbedingungen können sich ändern.'],['A legal promise of offsetting losses in every future market.','Eine Korrelation erzeugt keine Auszahlungsverpflichtung.'],['Proof that custody and withdrawal risks are irrelevant.','Diese Risiken liegen außerhalb der einfachen Renditekorrelation.']],['Portfolioeignung braucht zusätzlich Kosten-, Stress- und Zahlungsanalyse.'],'diversification'),
 q('73','d','An input reward percentage in a teaching calculator is:',[['An explicit scenario assumption requiring validation before any real application.','Die Rechnung zeigt Folgen der Annahme und beweist sie nicht.'],['An estimate guaranteed by the software to be achieved.','Eine Eingabe ist keine empirisch gesicherte Prognose.'],['A universal annual yield required by every proof-of-stake system.','Protokolle besitzen unterschiedliche Regeln und Risiken.']],['Modellergebnis und tatsächliche Annahmenqualität sind getrennte Fragen.'],'calculator'),
 q('74','d','Several digital products rely on the same custodian and bridge while holding correlated assets. Adding product names:',[['May leave common technical, liquidity and counterparty dependencies concentrated.','Namensvielfalt ist keine Unabhängigkeit der wirtschaftlichen Treiber.'],['Guarantees cancellation of every possible loss.','Gemeinsame Abhängigkeiten können gleichzeitig ausfallen.'],['Eliminates the need to inspect the underlying claim chain.','Gerade der Durchgriff zeigt die Gemeinsamkeiten.']],['Diversifikation wird nach tatsächlichen Risiken und nicht nur nach Anzahl beurteilt.'],'risk'),
 n('75','d','Additional model-intuition exercise: in the own fee-free equal-initial-value constant-product pool, the relative price ratio rises from 1 to 4 and arbitrage restores the pool’s price rule. Relative value difference versus holding the unchanged initial quantities is:',[['-20.00%.','Zweimal Wurzel vier geteilt durch fünf ergibt 0,8 des Haltevergleichs.'],['20.00%.','Das kehrt den relativen Nachteil um.'],['0.00%.','Das ignoriert die veränderten Poolmengen.']],'Z=100[2\\sqrt{4}/(1+4)-1]=-20','Die zusätzliche Herleitung misst relative Wertdifferenz und nicht automatisch einen absoluten Geldverlust.','defi','Relative Wertdifferenz zum unveränderten Haltebestand im vollständig bezeichneten Poolfall, Prozent.'),
 q('76','d','A stale or manipulated oracle price triggers collateral liquidation. The relevant concern is:',[['An external-data problem can create real transfers and liquidity losses even when the code follows its rules.','Technische Ausführung kann wirtschaftlich auf einer falschen Beobachtung beruhen.'],['The code’s execution proves the external price was accurate.','Konsens über eine Eingabe beweist nicht ihre Wahrheit.'],['Liquidation guarantees recovery of the original collateral valuation.','Zeit, Marktpreis und Kosten können den Erlös verändern.']],['Daten-, Markt- und Ausführungsrisiken können gemeinsam wirken.'],'oracle'),
 n('77','d','In an own continuous linear offer book, initial marginal price is 50 and rises by 0.2 per cumulative unit. No other costs or price changes occur. Total cost of buying 80 units is:',[['4640.00.','4000 Anfangsquote mal Menge plus 640 integrierter Preiseffekt.'],['4000.00.','Das verwendet die erste Quote für jede Einheit.'],['5280.00.','Das verwendet den höchsten Endpreis für die gesamte Menge.']],'Z=50(80)+0{,}2(80)^2/2=4640','Gesamtausgabe integriert die steigenden marginalen Kaufpreise.','liquidity','Gesamte modellierte Kaufzahlung, WE.'),
 n('78','d','An own equal-ranking proportional reserve liquidation realizes 80, pays prior costs 4 and settles total nominal claims 100. An investor originally paid one per nominal unit and receives only this final distribution. Investor loss percentage is:',[['24.00%.','76 von hundert werden bezahlt, 24 fehlen gegenüber dem eigenen Einstieg.'],['20.00%.','Das ignoriert die Abwicklungskosten.'],['4.00%.','Das zeigt nur die Kostenquote und lässt den Reserveverlust weg.']],'Z=100[1-(80-4)/100]=24','Reserveverluste und priorisierte Kosten gehören in denselben tatsächlichen Zahlungsweg.','reserve-case','Verlust relativ zum ausdrücklich bezahlten ursprünglichen Betrag, Prozent.'),
 q('79','d','A token balance grows while its fiat wealth declines. This outcome is:',[['Possible when price decline and other effects outweigh the quantity increase.','Geldwert ist Bestand mal Stückpreis.'],['Mathematically impossible because more units always mean more money.','Das setzt unverändert positiven Stückpreis ohne Prüfung voraus.'],['Proof that the ledger must have created an invalid transaction.','Ein ökonomischer Preisverlust ist nicht automatisch ein Registerfehler.']],['Mengen-, Preis- und Anspruchsänderungen müssen getrennt verfolgt werden.'],'quantity-case'),
 q('80','d','Before including a digital investment in a portfolio for a fixed future payment, the strongest assessment considers:',[['Loss capacity, executable exit, currency, claim enforceability and common stress exposures.','Der reale Zahlungszweck benötigt einen vollständigen Ertrags- und Liquiditätsweg.'],['Only whether its advertised gross reward exceeds the payment’s amount.','Eine Reward-Rate ist weder garantierter Geldwert noch verlässlicher Zahlungstermin.'],['Only continuous quoted trading hours.','Handelszeiten garantieren keine Tiefe oder erfolgreiche Auszahlung.']],['Eignung wird aus den Anlegerverpflichtungen und tatsächlichen Risiken abgeleitet.'],'due-diligence'),
 n('exam-a1','a c','A tokenized claim pays 135 in total. The stated vehicle first pays 15 of administration expense, then allocates the remaining cash equally across 40 tokens. The claim is actually received and no other flows or priorities exist. Payment per token is:',[['3.00.','120 tatsächlich verfügbare WE werden auf vierzig gleiche Ansprüche verteilt.'],['3.375.','Das verteilt den Bruttobetrag vor den ausdrücklich vorrangigen Kosten.'],['120.00.','Das ist der Gesamtbetrag und nicht die Zahlung je Einheit.']],'Z=(135-15)/40=3','Tokenisierung und Produkthülle erzeugen keinen zweiten Zahlungsstrom.','claims-case','Tatsächlich verteilte Nettozahlung je gleichberechtigtem Token, WE.','mock-a'),
 n('exam-a2','b d','An own two-year model assumes annual gross token reward 20%, a fee of 25% of new rewards, supply growth 5% annually and aggregate valuation decline 10% annually. A 10% quantity loss occurs exactly once after first-year reward and fee. No other flows apply. Wealth return is closest to:',[['-12.553061%.','Der jährliche Bestandsfaktor 1,15 wird mit dem Preisfaktor 0,90 durch 1,05 verbunden; der Verlustfaktor 0,90 wirkt einmal.'],['32.250000%.','Das zeigt nur Mengenwachstum ohne Verlust, Angebot und Preis.'],['-21.297755%.','Das wiederholt den einmaligen Verlust in beiden Jahren.']],'Z=100[0{,}9(1{,}15(0{,}9)/1{,}05)^2-1]\\approx-12{,}553061','Alle Mengen-, Preis-, Gebühren- und Zeitpunktannahmen werden genau einmal verbunden.','quantity-case','Gesamte zweijährige Vermögensrendite im reservierten vollständigen Modellfall, Prozent.','mock-a'),
 q('exam-b1','a c','A bank offers two digital products referencing the same bond. One is an issuer-recorded bond interest; the other is a cash-settled claim against a separate platform. Both report the same reference price. Which conclusion is most appropriate?', [['The analyst must trace the distinct legal claims, settlement conditions and counterparties before treating the products as equivalent.','Ein gleicher Referenzkurs macht Forderungsgegner und Anlegerrechte nicht identisch.'],['Both investors necessarily have the same direct rights against the bond issuer.','Der synthetische Weg kann nur den Plattformanspruch vermitteln.'],['A blockchain reference removes the platform’s default risk.','Die technische Abbildung garantiert nicht ihre Zahlungsfähigkeit.']],['Anwendung und Anlagevehikel müssen bis zum tatsächlich durchsetzbaren Anspruch untersucht werden.'],'rights','mock-b'),
 n('exam-b2','b d','An own portfolio starts 95% traditional assets and 5% digital assets. There is no rebalancing, and returns are -8% and -60% over the same period. No other flows occur. Portfolio return is:',[['-10.60%.','7,6 Prozentpunkte traditioneller Verlust und drei digitale Verlustbeiträge.'],['-34.00%.','Das verwendet einen ungewichteten statt des gegebenen gewichteten Durchschnitts.'],['-3.00%.','Das ist nur der Beitrag der digitalen Quote.']],'Z=0{,}95(-8)+0{,}05(-60)=-10{,}6','Die kleine volatile Position kann den gemeinsamen Verlust verstärken.','diversification','Gesamtrendite des reservierten Portfoliostressfalls, Prozent.','mock-b')
];
